// The menu of the documentation site. Pages named *.synced.md come from the repository's own
// documents (scripts/sync-docs.mjs); their ids end in ".synced".
import { existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const content = join(dirname(fileURLToPath(import.meta.url)), 'content');
/** An autogenerated category, only when the folder has pages (an empty one would fail the build). */
const folder = (label, dirName) =>
  existsSync(join(content, dirName)) ? [{ type: 'category', label, collapsed: true, items: [{ type: 'autogenerated', dirName }] }] : [];

/** @type {import('@docusaurus/plugin-content-docs').SidebarsConfig} */
export default {
  docs: [
    'index',
    {
      type: 'category',
      label: 'Using SovAI',
      collapsed: false,
      items: [
        'using/getting-started',
        'using/deployment-hardware',
        { type: 'category', label: 'By role', collapsed: false, items: [{ type: 'autogenerated', dirName: 'using/roles' }] },
        'using/features.synced',
        ...folder('Reference', 'using/reference')
      ]
    },
    {
      type: 'category',
      label: 'Security',
      items: ['security/trust-model', 'security/road-to-production', 'security/policy.synced', ...folder('Security documents', 'security/documents')]
    },
    ...folder('Accreditation', 'accreditation'),
    {
      type: 'category',
      label: 'Architecture',
      items: [
        'architecture/overview',
        ...folder('Component catalogue', 'architecture/components'),
        ...folder('Codebase', 'architecture/codebase'),
        ...folder('Design documents', 'architecture/design'),
        ...folder('Decision records', 'architecture/decisions')
      ]
    },
    {
      type: 'category',
      label: 'Developing',
      items: [
        'developing/contributing.synced',
        'developing/development-workflow.synced',
        'developing/testing.synced',
        'developing/docs-site.synced'
      ]
    },
    {
      type: 'category',
      label: 'Releases',
      items: ['releases/changelog.synced', 'releases/versions']
    }
  ]
};
